UMANO = {}
UMANO['7.1'] = [
 ["In questo modulo vediamo come si muovono i mercati gli uni rispetto agli altri. Perché quando sale il dollaro spesso scende l'oro? Perché lo yen sale quando le borse crollano? Ma prima di entrare nei casi, oggi capiamo cos'è una correlazione. E perché non va mai presa come una certezza."],
 ["La correlazione si misura con un numero che va da meno uno a più uno.",
  "Più uno: due asset si muovono sempre nella stessa direzione, nello stesso momento. Come due ballerini perfettamente sincronizzati.",
  "Zero: non c'è un legame stabile. Ognuno va per conto suo.",
  "Meno uno: si muovono sempre in direzioni opposte.",
  "Nella pratica vedi quasi sempre valori intermedi, come più zero virgola sei o meno zero virgola quattro. E soprattutto valori che cambiano nel tempo."],
 ["Le correlazioni cambiano per tre motivi principali.",
  "Primo: cambia il motore del mercato. Quando domina l'inflazione, certi asset si muovono insieme. Quando domina la paura di una recessione, se ne muovono insieme altri.",
  "Secondo: gli eventi straordinari. Nelle crisi più acute tante correlazioni saltano, perché tutti vendono tutto per fare cassa. Lo vediamo nel modulo sui beni rifugio.",
  "Terzo: i nuovi protagonisti. Quando un grande operatore comincia a comprare o vendere in modo costante, come le banche centrali con l'oro negli ultimi anni, i legami storici possono indebolirsi."],
 ["Ecco la correlazione tra dollaro e oro, calcolata sulle ultime cinquantadue settimane, dal duemilaotto. È quasi sempre negativa, in media meno zero virgola quarantasette. Ma guarda: non sta mai ferma. Nel duemilaquattordici si avvicina a meno zero virgola due, quasi nessun legame. Nel duemiladiciotto arriva a meno zero virgola settantatré. Lo stesso numero, calcolato in periodi diversi, racconta storie diverse."],
 ["Vediamo un esempio vero. Per tanti anni, quando le azioni scendevano, i titoli di Stato tendevano a salire. E questo rendeva i portafogli misti più stabili. Una specie di paracadute.",
  "Nel duemilaventidue, però, il motore del mercato era l'inflazione. Con le banche centrali che alzavano i tassi in fretta.",
  "Risultato: azioni e obbligazioni sono scese insieme. E tanti portafogli considerati prudenti hanno preso perdite importanti.",
  "La lezione? Una protezione basata sulle correlazioni del passato può non funzionare proprio quando ti serve di più. Il paracadute non si è aperto."],
 ["Riassumiamo.",
  "La correlazione misura quanto due asset si muovono insieme, da meno uno a più uno.",
  "Cambia nel tempo, a seconda di cosa guida il mercato. E nelle crisi può saltare del tutto.",
  "E sul piano del rischio: non contare mai su una correlazione per proteggere una posizione. Lo stop e il dimensionamento restano la tua difesa principale."],
]
UMANO['7.2'] = [
 ["La correlazione più citata tra i trader è quella tra dollaro e oro. Oggi vediamo perché esiste, come si osserva, e quando può non funzionare."],
 ["Il legame ha tre spiegazioni principali.",
  "La prima: l'oro si scambia in dollari. Quando il dollaro si rafforza, per chi compra con euro, yen o altre valute l'oro diventa più caro. E la domanda tende a calare.",
  "La seconda riguarda i tassi. Quando i tassi americani salgono, il dollaro rende di più. L'oro non rende niente. E alcuni investitori spostano soldi dall'oro al dollaro.",
  "La terza: per molti investitori dollaro e oro sono due modi alternativi di cercare sicurezza. Quindi, a volte, si fanno concorrenza."],
 ["Come si osserva questo legame, in pratica?",
  "Si usa l'indice del dollaro, il DXY. Misura il dollaro contro un paniere di sei valute principali, dove l'euro pesa più della metà.",
  "Metti sullo stesso grafico il DXY e l'oro, e vedrai che spesso vanno in direzioni opposte.",
  "Ed è particolarmente visibile nei giorni dei dati americani importanti. Un dato forte spinge su dollaro e rendimenti, e l'oro tende a scendere. E viceversa."],
 ["Ecco l'indice del dollaro, in blu, e l'oro, in giallo, dal duemilaquindici. Nel breve periodo spesso si muovono al contrario. Ma guarda gli ultimi anni: il dollaro resta forte... e l'oro sale lo stesso. Da circa milleduecentocinquanta dollari a oltre quattromila. Quando entra in gioco un motore più forte, come gli acquisti delle banche centrali, il legame con il dollaro passa in secondo piano."],
 ["E ci sono casi in cui il legame si rompe.",
  "Nei momenti di paura estrema, dollaro e oro possono salire insieme. Perché sono tutti e due considerati rifugi.",
  "Quando la domanda di oro arriva da fuori degli Stati Uniti, da banche centrali o investitori asiatici, l'oro può salire anche con un dollaro forte. È successo più volte dal duemilaventidue in poi.",
  "E nelle crisi di liquidità più acute, quando tutti vendono tutto, può scendere anche l'oro insieme agli altri. Lo vediamo nel prossimo modulo."],
 ["Riassumiamo.",
  "Dollaro e oro tendono a muoversi in direzioni opposte, per il prezzo in dollari e per il ruolo dei tassi.",
  "Il legame si osserva confrontando l'oro con l'indice del dollaro. Ed è più forte nei giorni dei dati americani.",
  "E sul piano del rischio: se sei corto sul dollaro e lungo sull'oro nello stesso momento, probabilmente stai facendo la stessa scommessa due volte. E il rischio totale è più alto di quanto sembra."],
]
UMANO['7.3'] = [
 ["Tra tutti i cambi, il dollaro yen è forse quello più legato ai tassi. Per anni il Giappone ha avuto tassi vicini allo zero, o negativi, mentre quelli americani salivano e scendevano. Oggi vediamo come questo crea uno dei legami più chiari di tutti i mercati."],
 ["Il meccanismo è il differenziale dei tassi, che abbiamo visto nel modulo due.",
  "Per tanti anni i tassi giapponesi sono rimasti vicini allo zero. Anzi, sotto zero tra il duemilasedici e il duemilaventiquattro.",
  "Con i tassi giapponesi quasi fermi, era soprattutto il movimento dei tassi americani a decidere quanto fosse ampio il differenziale.",
  "E il risultato è che il dollaro yen ha seguito molto da vicino i rendimenti americani. Rendimenti su, dollaro yen su. Rendimenti giù, dollaro yen giù."],
 ["Il duemilaventidue ne è un esempio chiarissimo. Durante quell'anno la Fed ha alzato i tassi molto in fretta per combattere l'inflazione.",
  "La Banca del Giappone, invece, ha tenuto i tassi negativi, e ha continuato a controllare i rendimenti dei titoli giapponesi.",
  "Quindi il differenziale tra i due paesi è esploso.",
  "E il dollaro yen è passato da circa centoquindici, a inizio anno, a oltre centocinquanta in ottobre. Ai massimi da più di trent'anni. A quel punto il governo giapponese è intervenuto sul mercato per sostenere lo yen. Lo vediamo nel modulo sugli eventi straordinari."],
 ["Ecco il decennale americano, in verde, e il dollaro yen, in rosso, dal duemilaventi. A gennaio duemilaventuno il rendimento è intorno all'uno per cento, e il cambio a centoquattro. Poi i rendimenti americani salgono, mentre in Giappone restano bassi. E il dollaro yen sale con loro, fino a centosessantadue a luglio duemilaventisei. In questo periodo la correlazione tra le due linee è altissima: zero virgola novantasette. Praticamente due gemelli."],
 ["Cosa vuol dire per chi fa trading su questo cambio?",
  "Prima di operare sul dollaro yen, dai un'occhiata al rendimento del decennale americano. Spesso anticipa, o accompagna, il movimento.",
  "I dati americani muovono il dollaro yen quasi quanto l'euro dollaro. Proprio perché passano dai rendimenti.",
  "E le riunioni della Banca del Giappone possono dare movimenti molto ampi. Soprattutto quando cambia politica dopo anni di immobilità."],
 ["Riassumiamo.",
  "Il dollaro yen tende a seguire i rendimenti americani, perché per anni i tassi giapponesi sono rimasti fermi vicino allo zero.",
  "Nel duemilaventidue il forte aumento dei tassi americani lo ha spinto ai massimi da oltre trent'anni.",
  "E sul piano del rischio: ai livelli estremi il governo giapponese può intervenire sul cambio. E provocare movimenti improvvisi di diversi punti in pochi minuti."],
]
UMANO['7.4'] = [
 ["Alcuni paesi esportano tantissime materie prime. E le loro valute tendono a seguire i prezzi di quello che vendono. Oggi vediamo i due casi più noti, il dollaro canadese e il dollaro australiano. E cosa vuol dire per chi fa trading."],
 ["Queste sono le valute più legate alle materie prime.",
  "Il dollaro canadese è legato al petrolio. Il Canada è uno dei maggiori esportatori al mondo, e lo vende soprattutto agli Stati Uniti.",
  "Il dollaro australiano è legato al minerale di ferro e ad altri metalli. L'Australia li esporta in enormi quantità, soprattutto verso la Cina.",
  "Il dollaro neozelandese è legato ai prodotti agricoli e ai latticini.",
  "E la corona norvegese al petrolio e al gas del Mare del Nord."],
 ["Il legame funziona così.",
  "Quando i prezzi delle materie prime salgono, il paese esportatore incassa più soldi dalle vendite all'estero.",
  "Le imprese convertono quegli incassi nella valuta locale. E questo aumenta la domanda di quella valuta.",
  "E poi l'economia ne beneficia, e la banca centrale è meno propensa a tagliare i tassi. Tutte cose che tendono a rafforzare la valuta."],
 ["Ecco il petrolio, in giallo, e il cambio dollaro canadese, in blu con la scala rovesciata. Dal duemiladieci al duemilasedici le linee si muovono quasi insieme. Quando il petrolio crolla da centosei dollari, a metà duemilaquattordici, a circa trenta, all'inizio del duemilasedici, il dollaro americano passa da uno virgola zero otto a uno virgola quarantadue contro il canadese. Ma dal duemilaventi il legame quasi sparisce. Le correlazioni tra materie prime e valute esistono. Però vanno ricontrollate, sempre."],
 ["Anche qui ci sono dei limiti.",
  "Il legame non è automatico. Nel breve periodo contano di più le decisioni della banca centrale e i dati interni, come lavoro e inflazione.",
  "Per il dollaro australiano contano tantissimo i dati sull'economia cinese. Perché la Cina è il suo cliente principale.",
  "E queste valute tendono a scendere quando c'è paura sui mercati, perché sono legate alla crescita globale. Ne parliamo nella prossima lezione, quella su risk on e risk off."],
 ["Riassumiamo.",
  "Il dollaro canadese è legato al petrolio, quello australiano ai metalli e alla Cina, il neozelandese all'agricoltura.",
  "Il legame passa da esportazioni, domanda di valuta e crescita. Ma non è automatico.",
  "E sul piano del rischio: se fai trading su queste valute, aggiungi al calendario i dati sulle scorte di petrolio americane e i principali dati cinesi."],
]
UMANO['7.5'] = [
 ["Nei commenti di mercato senti spesso due espressioni inglesi: risk on e risk off. Descrivono l'umore generale. Gli investitori hanno voglia di rischiare, o cercano sicurezza? Oggi vediamo cosa succede ai vari mercati nelle due fasi."],
 ["Nella fase di risk on, cioè di voglia di rischiare, gli investitori sono ottimisti e cercano rendimento. Le borse salgono. Le valute legate alla crescita, come il dollaro australiano, neozelandese e canadese, si rafforzano. Yen e franco svizzero tendono a indebolirsi. E i rendimenti dei titoli di Stato tendono a salire, perché si vendono titoli sicuri per comprare cose più rischiose.",
  "Nella fase di risk off, di paura, succede il contrario. Le borse scendono. Le valute della crescita perdono terreno. Yen, franco svizzero, e spesso l'oro, si rafforzano. E i titoli di Stato più sicuri vengono comprati come rifugio, quindi i loro rendimenti scendono."],
 ["Ecco l'S&P 500, in alto, e il VIX, il famoso indice della paura, in basso. Il VIX ha una media di circa venti. Ma nelle fasi di panico esplode. Il venti novembre duemilaotto arriva a ottanta virgola nove. Il sedici marzo duemilaventi a ottantadue virgola sette. E in quelle settimane la borsa scende con violenza: nel duemilaventi l'S&P 500 perde circa un terzo in un mese. Un terzo, in un mese! Questi sono i momenti di risk off puro."],
 ["Cosa fa passare il mercato da una fase all'altra?",
  "Possono essere i dati economici. Una serie di dati deboli fa temere una recessione, e il mercato passa in risk off.",
  "Possono essere eventi improvvisi: una guerra, il fallimento di una banca, uno shock politico.",
  "E possono essere le banche centrali. Una banca centrale molto più dura del previsto può spaventare. Mentre segnali di tagli possono riaccendere la voglia di rischiare."],
 ["Come lo usi, in pratica?",
  "Come lettura del contesto. Un'occhiata agli indici azionari, allo yen e all'oro ti dice in pochi secondi qual è l'umore del giorno.",
  "Come controllo delle tue posizioni. Se sei lungo sul dollaro australiano, lungo sull'indice americano, e corto sullo yen... in realtà hai tre posizioni che dipendono tutte dallo stesso umore. Una sola scommessa, tre volte.",
  "E come avvertimento. Il passaggio al risk off è di solito più rapido e violento del contrario. Perché la paura si diffonde molto più in fretta della fiducia. Si scende in ascensore, si sale a piedi."],
 ["Riassumiamo.",
  "In risk on salgono le borse e le valute della crescita, mentre i rifugi perdono terreno.",
  "In risk off succede il contrario: yen, franco svizzero, oro e titoli di Stato si rafforzano.",
  "E sul piano del rischio: il risk off arriva più veloce. E colpisce insieme tutte le posizioni che dipendono dall'ottimismo dei mercati."],
]
UMANO['7.6'] = [
 ["Chi fa trading sull'oro si accorge presto che alcuni strumenti si muovono spesso nella stessa direzione. L'argento, il platino, il dollaro australiano e quello neozelandese. Oggi vediamo perché succede, quanto è forte il legame per ciascuno, e quando si rompe."],
 ["Partiamo da una panoramica. Dal più legato all'oro al meno legato.",
  "L'argento ha di solito il legame più forte. È anche lui un metallo prezioso, e risponde agli stessi motori.",
  "Il platino ha un legame medio. È considerato prezioso, ma la sua domanda dipende soprattutto dall'industria.",
  "Il dollaro australiano ha anche lui un legame medio. L'Australia è tra i maggiori produttori d'oro al mondo, e le sue esportazioni ne beneficiano quando il prezzo sale.",
  "E il dollaro neozelandese ha il legame più debole. Si muove spesso insieme a quello australiano, perché le due economie sono vicine e molto legate."],
 ["C'è un motivo che spiega gran parte di questo legame. Ed è il dollaro.",
  "Oro, argento, dollaro australiano e dollaro neozelandese sono tutti quotati contro il dollaro americano. Hanno lo stesso denominatore.",
  "Quindi quando il dollaro si indebolisce, per esempio dopo un dato americano debole, tendono a salire tutti insieme.",
  "E quando il dollaro si rafforza, scendono insieme. Quindi buona parte della correlazione non viene dai metalli. Viene dal dollaro che hanno in comune."],
 ["Guardiamo meglio l'argento, il parente più stretto dell'oro.",
  "In percentuale si muove spesso più dell'oro, in su e in giù. Per questo molti lo chiamano un oro più nervoso.",
  "Il motivo è che più di metà della domanda di argento viene dall'industria: pannelli solari, elettronica. Quindi l'argento sente sia i motori dell'oro, sia il ciclo economico.",
  "C'è un indicatore molto seguito: il rapporto tra oro e argento. Cioè, quante once d'argento servono per comprare un'oncia d'oro. Quando l'economia preoccupa, il rapporto tende a salire. E a marzo duemilaventi ha superato quota cento."],
 ["Ecco oro e argento dal duemilaquindici, partendo tutti e due da cento. Si muovono nella stessa direzione: la correlazione tra le variazioni mensili è zero virgola settantadue. Ma l'argento fa movimenti più ampi, in salita e in discesa. Nel periodo l'oro si moltiplica per tre virgola tre, l'argento per tre virgola cinque, con oscillazioni molto più forti. Quindi, con lo stesso lotto, l'argento rischia di più."],
 ["Però questi legami non valgono sempre.",
  "Nella paura acuta l'oro sale come rifugio, mentre dollaro australiano e neozelandese scendono insieme alle borse. Come abbiamo visto con il risk off.",
  "Quando l'economia rallenta, argento e platino soffrono più dell'oro. Perché cala la domanda industriale.",
  "E ognuno ha le sue notizie locali. La banca centrale australiana, i dati cinesi, problemi nelle miniere. Possono muoverli anche quando l'oro sta fermo."],
 ["Riassumiamo.",
  "L'argento è il parente più stretto dell'oro. Platino, dollaro australiano e neozelandese hanno un legame più debole.",
  "Gran parte della correlazione viene dal dollaro, che hanno tutti in comune.",
  "E sul piano del rischio: l'argento si muove più dell'oro. Quindi, a parità di rischio, serve un lotto più piccolo. Nella prossima lezione vediamo il legame con la borsa americana, e come usare tutto questo in pratica."],
]
UMANO['7.7'] = [
 ["Tanti pensano che oro e borsa vadano sempre in direzioni opposte, perché l'oro è un rifugio. In realtà, negli ultimi anni, oro e borsa americana sono saliti spesso insieme. Oggi capiamo perché. E poi vediamo come usare tutte queste correlazioni nel trading di tutti i giorni."],
 ["Nella prima fase, oro e borsa salgono insieme. Succede quando il motore sono i tassi. Se il mercato si aspetta tagli della Fed, i rendimenti reali scendono e il dollaro si indebolisce. Il denaro costa meno per tutti. E questo sostiene sia l'oro che le azioni.",
  "Nella seconda fase vanno in direzioni opposte. Succede quando il motore è la paura: una crisi, una tensione geopolitica. Le borse scendono, e l'oro sale come rifugio."],
 ["Guardiamo tre periodi veri, per vedere quanto cambia questo rapporto.",
  "Marzo duemilaventi: nella corsa alla liquidità, per qualche giorno sono scesi sia la borsa che l'oro. Tutto in vendita.",
  "Duemilaventidue, l'anno dei grandi rialzi dei tassi: la borsa americana perde circa il diciannove per cento, e l'oro chiude l'anno quasi invariato.",
  "Duemilaventiquattro: la Fed comincia a tagliare, le banche centrali comprano oro. E salgono tanto tutti e due. L'oro di circa il ventisette per cento, la borsa americana di circa il ventitré."],
 ["Quando si parla di borsa americana, nel trading si usano quasi sempre i futures sugli indici. Oppure i CFD che li replicano.",
  "Il più seguito è l'S&P 500, con il future E S e la sua versione piccola, il micro M E S. Dai broker lo trovi spesso con il nome u esse cinquecento.",
  "Poi c'è il Nasdaq 100, l'indice dei grandi titoli tecnologici, con il future N Q e il micro M N Q. Dai broker, spesso, u esse cento.",
  "E il Dow Jones, con il future Y M e il micro M Y M. Dai broker lo trovi come u esse trenta."],
 ["E perché i futures interessano a chi segue l'oro?",
  "Perché si scambiano quasi ventiquattro ore su ventiquattro, dalla domenica sera al venerdì, con una breve pausa ogni sera. Quindi li puoi confrontare con l'oro in qualsiasi momento.",
  "Perché reagiscono subito ai dati americani delle quattordici e trenta, prima che apra Wall Street, che di solito apre alle quindici e trenta ora italiana. Nei minuti del dato vedi in tempo reale se oro e futures si muovono insieme o al contrario.",
  "E perché il Nasdaq è di solito l'indice più sensibile ai tassi. Proprio come l'oro. Quindi, quando il motore sono i tassi, oro e Nasdaq tendono a muoversi insieme più degli altri."],
 ["Primo uso pratico: capire cosa sta muovendo l'oro, guardando i suoi parenti.",
  "Se oro, argento e dollaro australiano salgono insieme, il movimento è ampio. E di solito lo guidano dollaro e tassi.",
  "Se l'oro sale mentre dollaro australiano e borse scendono, lo guida la paura. L'oro sta facendo da rifugio.",
  "Se oro e borse salgono insieme, il motore sono probabilmente i tassi reali in calo e la liquidità. E sapere qual è il motore ti dice quali notizie potrebbero girare il movimento."],
 ["Secondo uso pratico, il più importante: il rischio.",
  "Essere lunghi su oro, argento e dollaro australiano non è diversificazione. È una sola scommessa contro il dollaro. E va trattata come un'unica posizione. Lo vediamo nella prossima lezione.",
  "L'argento si muove più dell'oro, quindi a parità di rischio serve un lotto più piccolo, calcolato sulla distanza dello stop. Sui futures il valore del punto è fisso: sull'S&P 500, per esempio, un punto vale cinquanta dollari sul contratto intero e cinque sul micro. Quindi il numero di contratti si calcola partendo dallo stop. Come sempre.",
  "Se l'oro sale ma i suoi parenti non lo seguono, prendilo come un avviso. Più prudenza. Non è un segnale per entrare o uscire, ma un motivo per non aumentare il rischio.",
  "E ricontrolla spesso. Queste correlazioni cambiano. Guardale sugli ultimi mesi, non su quello che succedeva anni fa."],
 ["Riassumiamo.",
  "Oro e borsa americana salgono insieme quando il motore sono i tassi in calo. E vanno in direzioni opposte quando il motore è la paura.",
  "Guardare argento, dollaro australiano e borse insieme all'oro ti aiuta a capire cosa sta muovendo il prezzo.",
  "E sul piano del rischio: più posizioni sulla famiglia dell'oro sono una sola scommessa. E il loro rischio va sommato. È proprio il tema della prossima lezione."],
]
UMANO['7.8'] = [
 ["Chiudiamo il modulo sulle correlazioni con la lezione più importante per il rischio. Tanti trader pensano di essere diversificati perché hanno posizioni su strumenti diversi. E invece stanno facendo la stessa scommessa più volte. Vediamo come accorgersene. E cosa fare."],
 ["Facciamo un esempio. Hai una posizione lunga sull'euro dollaro, con l'uno per cento di rischio.",
  "Ne hai una lunga sulla sterlina dollaro, con un altro uno per cento.",
  "E una lunga sull'oro, sempre all'uno per cento.",
  "Sembrano tre operazioni diverse, vero? In realtà sono tre scommesse contro il dollaro. Se esce un dato americano molto forte, probabilmente vanno male tutte e tre insieme. E il tuo rischio reale si avvicina al tre per cento. Su un unico evento."],
 ["Come te ne accorgi? Con tre domande semplici.",
  "Per ogni posizione, chiediti qual è l'idea di fondo. Cosa deve succedere perché funzioni?",
  "Raggruppa le posizioni per fattore comune. Il dollaro, l'umore dei mercati, i tassi, il petrolio.",
  "E somma il rischio di ogni gruppo. Trattalo come se fosse un'unica posizione. Perché, in pratica, lo è."],
 ["Una volta capito il problema, la soluzione è semplice.",
  "Fissa un tetto di rischio per ogni fattore. Per esempio, non più del due per cento in tutto su posizioni che dipendono dal dollaro.",
  "Se vuoi comunque più posizioni correlate, dividi il rischio tra loro. Per esempio tre posizioni allo zero virgola sei per cento ciascuna, invece che all'uno.",
  "E ricorda che un solo dato può colpire tutto il gruppo nello stesso momento. Quindi questa regola conta ancora di più nei giorni pieni di dati."],
 ["Riassumiamo, e chiudiamo il modulo.",
  "Posizioni su strumenti diversi possono essere la stessa scommessa. E moltiplicare il rischio.",
  "Per accorgertene, raggruppa le posizioni per fattore comune e somma il loro rischio.",
  "E la regola pratica è un tetto di rischio per ogni fattore. Nel prossimo modulo parliamo dei beni rifugio."],
]
